'use client'

import { useState } from 'react'
import { date } from './format'
import type { ScanMeta } from './types'

type Props = {
  scan: ScanMeta
  /** The weekly report — the HTML the CLI generated. */
  weekly: string
  /** The file-type report, as CSV. */
  csv: string
}

/**
 * The weekly HTML report and the file-type CSV.
 *
 * Both were generated by the CLI over the sample disk; the report is shown
 * in an iframe, exactly as the desktop app shows it.
 */
export default function Reports({ scan, weekly, csv }: Props) {
  const [html, setHtml] = useState('')
  const [shown, setShown] = useState('')

  return (
    <>
      <div className="workspace-heading">
        <h1>Reports</h1>
        <span className="summary">Why is the disk full?</span>
      </div>

      <div className="workspace-content">
        <div className="panel">
          <h3>Weekly report</h3>
          <p style={{ color: 'var(--dim)', fontSize: 12.5, marginTop: 0 }}>
            A self-contained HTML report with the file-type breakdown, the growth since the
            baseline snapshot and the largest folders. Generated locally — no data leaves this
            machine.
          </p>
          <button className="button primary" onClick={() => setHtml(weekly)}>
            Generate weekly report
          </button>
        </div>

        {html && (
          <div className="panel">
            <h3>Preview</h3>
            <iframe
              title="Weekly report"
              srcDoc={html}
              style={{
                width: '100%',
                height: 520,
                border: '1px solid var(--border)',
                borderRadius: 8,
                background: '#0d1117',
              }}
            />
          </div>
        )}

        <div className="panel">
          <h3>File-type report (CSV)</h3>
          <p style={{ color: 'var(--dim)', fontSize: 12.5, marginTop: 0 }}>
            The per-type size and share of the scanned bytes, as CSV.
          </p>
          <button className="button" onClick={() => setShown(csv)}>
            Generate CSV report
          </button>
        </div>

        {shown && (
          <div className="panel">
            <h3>CSV</h3>
            <pre
              style={{
                margin: 0,
                fontSize: 12,
                overflow: 'auto',
                maxHeight: 280,
                color: 'var(--text)',
              }}
            >
              {shown}
            </pre>
            <button
              className="button small"
              style={{ marginTop: 10 }}
              onClick={() => {
                const blob = new Blob([shown], { type: 'text/csv' })
                const url = URL.createObjectURL(blob)
                const link = document.createElement('a')
                link.href = url
                link.download = 'diskgoup-file-types.csv'
                link.click()
                URL.revokeObjectURL(url)
              }}
            >
              Download CSV
            </button>
          </div>
        )}

        <div className="notice">
          Measured from a scan taken {date(scan.started_at)}. Files inside cache and log
          folders count only in that group, so nothing is counted twice.
        </div>
      </div>
    </>
  )
}
